import{_ as i,C as l,o as r,c as n,j as a,a as d,b as s,w as e,E as h,a1 as E,a0 as A}from"./chunks/framework.DzvPB4Y-.js";const _=JSON.parse('{"title":"从业务示例接入自己的应用","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/integration.md","filePath":"zh-cn/frameworks/integration.md"}'),b={name:"zh-cn/frameworks/integration.md"};function p(B,t,m,c,f,u){const o=l("Mermaid");return r(),n("div",null,[t[1]||(t[1]=a("h1",{id:"从业务示例接入自己的应用",tabindex:"-1"},[d("从业务示例接入自己的应用 "),a("a",{class:"header-anchor",href:"#从业务示例接入自己的应用","aria-label":'Permalink to "从业务示例接入自己的应用"'},"​")],-1)),t[2]||(t[2]=a("p",null,"完成任意一课后，不必先接入 HTTP 服务。先做一个只依赖业务框架的小型应用：读一份固定输入，完成一次真实调用，输出可以逐项复核的结果。等输入、结果和错误处理稳定后，再接数据库、队列或 UI。",-1)),t[3]||(t[3]=a("h2",{id:"_1-从最小调用流程开始",tabindex:"-1"},[d("1. 从最小调用流程开始 "),a("a",{class:"header-anchor",href:"#_1-从最小调用流程开始","aria-label":'Permalink to "1. 从最小调用流程开始"'},"​")],-1)),(r(),s(E,null,{default:e(()=>[h(o,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E8%AE%A2%E5%8D%95%E4%B8%8E%E8%B5%84%E6%BA%90%E5%BF%AB%E7%85%A7%5D%20--%3E%20B%5B%E4%B8%9A%E5%8A%A1%E9%80%82%E9%85%8D%E4%B8%8E%E5%8D%95%E4%BD%8D%E6%A0%A1%E9%AA%8C%5D%0A%20%20%20%20B%20--%3E%20C%5B%E9%A2%86%E5%9F%9F%E9%97%AE%E9%A2%98%E4%B8%8E%E9%85%8D%E7%BD%AE%5D%0A%20%20%20%20C%20--%3E%20D%5B%E6%A1%86%E6%9E%B6%E5%8F%8A%E6%B1%82%E8%A7%A3%E5%90%8E%E7%AB%AF%5D%0A%20%20%20%20D%20--%3E%20E%5B%E6%B1%82%E8%A7%A3%E7%8A%B6%E6%80%81%E6%A3%80%E6%9F%A5%E4%B8%8E%E4%B8%9A%E5%8A%A1%E5%A4%8D%E6%A0%B8%5D%0A%20%20%20%20E%20--%3E%20F%5B%E4%B8%9A%E5%8A%A1%E7%BB%93%E6%9E%9C%E4%B8%8E%E5%AE%A1%E8%AE%A1%E8%AE%B0%E5%BD%95%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=A('<p>各框架的入口与返回类型不同，这不是一个可以直接复制的统一 API。箭头表示应用职责；不要为了统一接口而丢掉原始报告、物理量或错误信息。</p><table tabindex="0"><thead><tr><th>层次</th><th>应当放什么</th><th>不应当放什么</th></tr></thead><tbody><tr><td>输入适配</td><td>订单 ID、单位、时间、库存与资源的显式转换</td><td>隐式补零、静默丢订单、按尺寸合并不同 ID</td></tr><tr><td>应用调用</td><td>领域问题、配置、后端、时限、扩展配置</td><td>再实现一份框架已有的守恒或重叠公式</td></tr><tr><td>业务规则</td><td>单个候选方案策略或全局建模扩展</td><td>只在导出报表时才发现硬约束违反</td></tr><tr><td>结果适配</td><td>已验证方案、状态、指标、缺口与诊断</td><td>将模拟结果、空渲染对象或未找到可行解的报告当成业务方案</td></tr></tbody></table><h2 id="_2-从示例到业务应用-依次改五处" tabindex="-1">2. 从示例到业务应用，依次改五处 <a class="header-anchor" href="#_2-从示例到业务应用-依次改五处" aria-label="Permalink to &quot;2. 从示例到业务应用，依次改五处&quot;">​</a></h2><ol><li><strong>保留手算基准</strong>：先运行第一课的业务函数和 <code>main</code>，确认数据、后端与结果读取接通；不要先替换成全部生产订单。</li><li><strong>确认实际求解方式</strong>：需要原生求解器的示例应配置实际后端；使用默认启发式的示例应如实标明算法。BPP2D/BPP3D 要分别配置受限主问题和最终整数求解的后端，并保留各阶段报告。</li><li><strong>处理请求边界错误</strong>：第一课在命令行程序中抛出异常或返回错误，接入服务端时应转换为结构化响应；未找到可行解时保留原始报告。各 API 的外层返回类型并不相同。</li><li><strong>一次替换一类数据</strong>：先需求，再资源，最后加规则。保留能手算的小问题，逐项检查件数守恒、库存上限等必须始终满足的业务规则。</li><li><strong>最后接基础设施</strong>：加入数据库、队列与 UI；避免过期结果覆盖新请求，诊断日志脱敏，不记录许可证和凭据。</li></ol><p>按<a href="./setup.html">环境页</a>配置依赖与原生库。第一课源码含完整导入；同名 Kotlin/Rust 构造器不一定可以互换。</p><h2 id="_3-输入进入模型前要检查什么" tabindex="-1">3. 输入进入模型前要检查什么？ <a class="header-anchor" href="#_3-输入进入模型前要检查什么" aria-label="Permalink to &quot;3. 输入进入模型前要检查什么？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输入</th><th>需要作出的业务决定</th></tr></thead><tbody><tr><td>ID 与引用</td><td>是否唯一，所有产品、箱型、资源、节点引用是否存在</td></tr><tr><td>数量与单位</td><td>件/卷是否为整数，长度/重量如何转换，零需求是否保留</td></tr><tr><td>库存与上界</td><td>未提供是否表示不限；不能把 <code>null</code>、零和缺失字段混用</td></tr><tr><td>时间与日历</td><td>时区、允许起点、执行区间、冻结规则和已实际执行记录</td></tr><tr><td>目标</td><td>优先箱数、消耗、费用还是服务水平；权重采用什么归一化规则</td></tr><tr><td>预算</td><td>候选数、节点数、迭代和总时限；预算耗尽后怎样展示现有方案</td></tr></tbody></table><p>请求取消和求解时限应使用实际后端支持的接口。若只停止等待、后端仍在计算，应明确区分这两种状态，并防止过期结果覆盖新一轮排程。</p><h2 id="_4-返回成功之后-还要分两层判断" tabindex="-1">4. 返回成功之后，还要分两层判断 <a class="header-anchor" href="#_4-返回成功之后-还要分两层判断" aria-label="Permalink to &quot;4. 返回成功之后，还要分两层判断&quot;">​</a></h2><p>外层调用成功只表示拿到了报告或结果；报告内仍可能是不可行、达到时限但未找到可行解、达到时限且已有可行解，或已证明最优。具体枚举和字段以对应语言源码为准。</p><table tabindex="0"><thead><tr><th>观察</th><th>应用应做什么</th></tr></thead><tbody><tr><td>输入或技术错误</td><td>返回可定位的错误，不展示旧方案冒充本次成功</td></tr><tr><td>正常终止但无可交付方案</td><td>展示原因与诊断；区分完整问题不可行和当前候选不足</td></tr><tr><td>已找到可行解</td><td>先完成业务复核，再按真实求解状态交付；限时不能改成最优</td></tr><tr><td>当前模型被证明最优</td><td>记录模型范围、候选完整性、额外规则及证明来源</td></tr><tr><td>几何/库存/工艺复核失败</td><td>不交付，保留输入与原始报告，检查建模或提取路径</td></tr></tbody></table><p>推荐业务输出至少包含请求/输入版本、采用的配置、实际后端、可交付性、原始求解状态、目标与单位、方案、缺口和诊断。<strong>这是应用层建议，不是 OSPF 保证存在的统一序列化数据结构。</strong> 没有目标界限或最优性差距时写“未提供”，不要补为零。</p><h2 id="_5-用三组用例保护接入" tabindex="-1">5. 用三组用例保护接入 <a class="header-anchor" href="#_5-用三组用例保护接入" aria-label="Permalink to &quot;5. 用三组用例保护接入&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用例组</th><th>例子</th><th>验收</th></tr></thead><tbody><tr><td>可行基准</td><td>一箱装载、一个图案、两活动、四节点流</td><td>精确数量、几何/工艺/守恒、资源与重算费用</td></tr><tr><td>刻意不可行</td><td>单件超长、冻结与停机冲突、共享资源不足</td><td>不生成伪方案；报告范围正确</td></tr><tr><td>边界与故障</td><td>重复 ID、错单位、零库存、后端失败、限时无解</td><td>不静默改输入；技术错误与业务求解状态分开</td></tr></tbody></table><p>测试时同时检查业务规则和目标值。多个等价最优方案可能使用不同坐标或活动次序；应优先检查件数、库存、资源等要求，以及目标值的允许误差。只有业务确实要求固定顺序时，才限定具体方案。</p><p>第二课的手算场景可作为业务验收基准，输入构造和规则示例可用于接入。请用自己的输入和求解后端验证扩展后的完整问题；链接中的源码测试主要用于核对单项能力。</p><h2 id="_6-继续一个具体场景" tabindex="-1">6. 继续一个具体场景 <a class="header-anchor" href="#_6-继续一个具体场景" aria-label="Permalink to &quot;6. 继续一个具体场景&quot;">​</a></h2><ul><li><a href="./bpp1d/business-scenario.html">BPP1D：多容器类型、库存与费用</a></li><li><a href="./bpp2d/business-scenario.html">BPP2D：多板型、旋转与间距</a></li><li><a href="./bpp3d/business-scenario.html">BPP3D：多箱型与目标配置</a></li><li><a href="./csp1d/business-scenario.html">CSP1D：需求计量与业务规则</a></li><li><a href="./csp2d/business-scenario.html">CSP2D：刀缝、工艺与卷材</a></li><li><a href="./gantt/business-scenario.html">Gantt：停机日历与滚动重排</a></li><li><a href="./network/business-scenario.html">Network：共享资源、缺货与联合模型</a></li></ul><p>添加自定义规则时，先判断规则影响的范围：只影响一个候选方案的规则放在生成器或策略接口；影响多个候选方案或多个领域的规则进入联合模型。更多说明见<a href="/ospf/zh-cn/guide/modeling-workflow.html">建模流程</a>、<a href="/ospf/zh-cn/guide/solving-results.html">求解结果</a>和<a href="./#terminology">常用术语</a>。</p>',19))])}const P=i(b,[["render",p]]);export{_ as __pageData,P as default};
